	private static void register(String itemId, int tab, int order) {
		ALL_ENTRIES.computeIfAbsent(itemId, k -> new ArrayList<>()).add(new int[]{tab, order});
		TAB_ITEMS.computeIfAbsent(tab, k -> new ArrayList<>()).add(itemId);
	}

	public static int getTab(String registryName) {
		if (registryName == null) return UNKNOWN;
		List<int[]> entries = ALL_ENTRIES.get(registryName);
		if (entries == null || entries.isEmpty()) return UNKNOWN;
		int best = Integer.MAX_VALUE;
		for (int[] e : entries) if (e[0] < best) best = e[0];
		return best;
	}

	public static int getOrder(String registryName) {
		if (registryName == null) return Integer.MAX_VALUE;
		int tab = getTab(registryName);
		List<int[]> entries = ALL_ENTRIES.get(registryName);
		if (entries == null) return Integer.MAX_VALUE;
		for (int[] e : entries) if (e[0] == tab) return e[1];
		return Integer.MAX_VALUE;
	}

	/**
	 * Returns the official list of item registry IDs for the given tab,
	 * in official order. An item may appear in multiple tabs.
	 * Used by SortedCreativeTab to populate each creative tab by walking
	 * official data and skipping unimplemented items.
	 */
	public static List<String> getItemsForTab(int tab) {
		List<String> list = TAB_ITEMS.get(tab);
		return list != null ? list : Collections.<String>emptyList();
	}

	/**
	 * Returns all official item IDs registered in this data (across all tabs).
	 * Used by the debug dump to identify which official items are missing.
	 */
	public static Set<String> getAllItemIds() {
		return ALL_ENTRIES.keySet();
	}
